import{_ as t,C as s,o as n,c as l,a2 as c,j as a,a as r,E as i}from"./chunks/framework.Di-jvWLj.js";const w=JSON.parse('{"title":"Concurrency, Leases & Multi-Replica","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concurrency.md","filePath":"guide/concurrency.md","lastUpdated":1792243762000}'),d={name:"guide/concurrency.md"},u={id:"cron-across-replicas",tabindex:"-1"};function h(p,e,m,g,y,k){const o=s("Badge");return n(),l("div",null,[e[3]||(e[3]=c('<h1 id="concurrency-leases-multi-replica" tabindex="-1">Concurrency, Leases &amp; Multi-Replica <a class="header-anchor" href="#concurrency-leases-multi-replica" aria-label="Permalink to &quot;Concurrency, Leases &amp; Multi-Replica&quot;">​</a></h1><p>Several engines can share one store. They coordinate through the store alone: run claims are leases, concurrency keys are checked under store locks, and idempotency keys are claimed atomically. There is no leader and no extra service.</p><div class="warning custom-block"><p class="custom-block-title">Durable store required</p><p><code>MemoryStore</code> lives in one process, so replicas cannot share it. Running several replicas needs a durable, shared store such as the planned <a href="/stores/typeorm">Postgres store</a>.</p></div><h2 id="local-slots" tabindex="-1">Local slots <a class="header-anchor" href="#local-slots" aria-label="Permalink to &quot;Local slots&quot;">​</a></h2><p><code>maxConcurrentRuns</code> (default <code>4</code>) caps the runs one engine executes at once. A scheduling pass lists <code>queued</code> runs in FIFO order (by <code>createdAt</code>, then <code>id</code>) and starts them until the slots are full. Passes run after a dispatch, after a run settles, after a resume and on every poll.</p><p>A <code>waiting</code> run holds no slot. A long approval wait does not block other work.</p><h2 id="concurrency-keys" tabindex="-1">Concurrency keys <a class="header-anchor" href="#concurrency-keys" aria-label="Permalink to &quot;Concurrency keys&quot;">​</a></h2><p>A run with a <code>concurrencyKey</code> starts only when no other run of the same agent and key is <code>running</code>, <code>waiting</code> or <code>interrupted</code>. The check, the claim and the move to <code>running</code> happen under the store lock <code>concurrency:&lt;agent&gt;:&lt;key&gt;</code>, so two replicas cannot both start a run for the same key. A blocked run stays <code>queued</code> and later runs with other keys start past it.</p><p>Note what blocks a key:</p><ul><li><code>waiting</code>: a run paused on an approval keeps its key, so the next run for the same issue does not start while the owner decides.</li><li><code>interrupted</code>: a drained run keeps its key until it is recovered and finished.</li></ul><h2 id="claims-are-leases" tabindex="-1">Claims are leases <a class="header-anchor" href="#claims-are-leases" aria-label="Permalink to &quot;Claims are leases&quot;">​</a></h2><p>A run is executed by the engine that holds its claim. <code>claimRun(id, owner, claimTtlMs)</code> takes the lease (default 60 s) and the engine renews it every <code>claimTtlMs / 3</code> while the run executes.</p><ul><li><strong>Owner:</strong> <code>owner</code> identifies the replica, by default <code>&lt;hostname&gt;-&lt;pid&gt;</code>. Give each replica a distinct owner.</li><li><strong>Conditional writes:</strong> every write of a running run checks the status and that this owner still holds the claim.</li><li><strong>Lost lease:</strong> when a renewal is refused, or another owner took the run over after the lease expired, the engine aborts its execution, writes nothing more and reports a <code>LeaseLostError</code> to <code>onError</code>. The new owner continues from the latest checkpoint.</li></ul><h2 id="the-poll" tabindex="-1">The poll <a class="header-anchor" href="#the-poll" aria-label="Permalink to &quot;The poll&quot;">​</a></h2><p>Every <code>claimTtlMs / 3</code> each started engine:</p><ol><li>runs <code>tick()</code>: denies expired approvals and re-sends undelivered approval notifications,</li><li>runs <code>recover()</code>: requeues <code>running</code> or <code>interrupted</code> runs whose claim expired or was released, and aborts local runs another replica asked to cancel,</li><li>runs a scheduling pass.</li></ol><p>So a crashed replica&#39;s runs are picked up by another replica within about one lease plus one poll interval.</p><h2 id="tuning-claimttlms" tabindex="-1">Tuning <code>claimTtlMs</code> <a class="header-anchor" href="#tuning-claimttlms" aria-label="Permalink to &quot;Tuning `claimTtlMs`&quot;">​</a></h2><p>A shorter lease recovers crashed runs sooner and polls more often. A longer lease tolerates longer pauses (a slow store, a stop-the-world GC) before another replica takes a run over. The default of 60 s polls every 20 s.</p>',19)),a("h2",u,[e[0]||(e[0]=r("Cron across replicas ",-1)),i(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=r()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#cron-across-replicas","aria-label":'Permalink to "Cron across replicas <Badge type="warning" text="Planned" />"'},"​",-1))]),e[4]||(e[4]=a("p",null,[r("Firing a cron trigger once across replicas needs a per-tick lock. The planned "),a("a",{href:"/roadmap#planned-packages"},[a("code",null,"@chamberu/scheduler")]),r(" takes a store lock per "),a("code",null,"(trigger, scheduledAt)"),r(" and dispatches with an idempotency key built from the same pair, so a second firing is harmless even if the lock failed. See "),a("a",{href:"/deployment/replicas"},"Multiple Replicas"),r(".")],-1))])}const b=t(d,[["render",h]]);export{w as __pageData,b as default};
